    };
    switch (e.key) {
      case "ArrowDown":
        return move(active + 1);
      case "ArrowUp":
        return move(active - 1);
      case "Home":
        return move(0);
      case "End":
        return move(last);
      case "PageDown":
        return move(active + 8);
      case "PageUp":
        return move(active - 8);
      case "Enter":
        e.preventDefault();
        return pick(active);
      case " ":
        e.preventDefault();
        // A space in the middle of type-ahead is part of the name ("Chinese (Trad…").
        if (typed.current.text && Date.now() - typed.current.at < 500) {
          const i = typeahead(" ", active);
          if (i !== null) setActive(i);
          return;
        }
        return pick(active);
      case "Escape":
        e.preventDefault();
        // Don't let an enclosing panel/dialog close on the same Escape.
        e.stopPropagation();
        return close(true);
      case "Tab":
        // Let focus move on; just close.
