                <span className="min-w-0 flex-1 truncate">{o.label}</span>
                {isSelected ? <CheckIcon size={14} className="shrink-0" /> : <span className="w-3.5 shrink-0" aria-hidden="true" />}
              </li>
            );
          })}
        </ul>
      )}
    </div>
